makeMtLab(document.getElementById("lab-l78"),{id:"l78",scenarios:[{"label": "Ví dụ: Phát lệnh", "note": "NEW → RELEASED.", "steps": [{"t": "WO-0413 NEW", "html": "<p class=\"mt-calc\">Kế hoạch viên chọn L1, seq = 3<\/p>"}, {"t": "transition(RELEASED)", "html": "<p class=\"mt-calc\">Xuất hiện trong hàng đợi L1<\/p>", "ask": {"q": "Lệnh RELEASED đã chạy chưa?", "o": ["Rồi", "Chưa, đang chờ"], "a": 1}}]}, {"label": "Ví dụ: Bắt đầu khi lệnh khác đang chạy", "note": "Chỉ mục một phần.", "steps": [{"t": "WO-0412 RUNNING trên L1", "html": "<p class=\"mt-calc\">Thử bắt đầu WO-0413<\/p>"}, {"t": "CSDL", "html": "<p class=\"mt-calc\">Lỗi duplicate key → API 409<\/p>"}]}, {"label": "Ví dụ: Gom sản phẩm", "note": "Đổi thứ tự.", "steps": [{"t": "Thứ tự gốc: SP-07, SP-08, SP-07", "html": "<p class=\"mt-calc\">2 lần đổi<\/p>"}, {"t": "Sau khi gom: SP-07, SP-07, SP-08", "html": "<p class=\"mt-calc\">1 lần đổi, tiết kiệm ≈ 25 phút<\/p>"}]}, {"label": "Lỗi: Chỉ kiểm tra ở ứng dụng", "note": "SELECT rồi UPDATE.", "steps": [{"t": "Hai máy tính bảng bấm cùng lúc", "html": "<p class=\"mt-calc\">Cả hai thấy chưa có lệnh chạy<\/p>"}, {"t": "Kết quả", "html": "<p class=\"mt-calc\">Hai lệnh RUNNING<\/p>", "say": "<p>Ràng buộc trong CSDL không có khe hở này.<\/p>"}]}, {"label": "Bẫy: Gom làm trễ hạn", "note": "Chỉ tối ưu đổi sản phẩm.", "steps": [{"t": "Lệnh gấp SP-08 bị đẩy cuối", "html": "<p class=\"mt-calc\">Trễ giao<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">Hạn giao là ràng buộc, đổi sản phẩm là mục tiêu<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l78"),"l78",[{"kind": "num", "t": "Hàng đợi", "d": "<p>Trả lời bằng một số.<\/p>", "items": [{"q": "Thứ tự SP-07, SP-08, SP-07, SP-08. Bao nhiêu lần đổi sản phẩm?", "a": 3}, {"q": "Gom lại SP-07, SP-07, SP-08, SP-08. Bao nhiêu lần đổi?", "a": 1}, {"q": "Mỗi lần đổi 25 phút. Tiết kiệm bao nhiêu phút?", "a": 50}], "hints": ["Đếm số lần sản phẩm khác lệnh trước.", "Chênh lệch × 25."], "why": "3; 1; 50."}, {"kind": "pick", "t": "Chặn ở đâu?", "d": "<p>Ràng buộc nào chặn tình huống?<\/p>", "cats": ["Chỉ mục một phần", "transition()", "UNIQUE erp_ref"], "items": [{"q": "Hai lệnh RUNNING trên L1", "a": 0}, {"q": "RELEASED → COMPLETED", "a": 1}, {"q": "ERP gửi lại cùng lệnh", "a": 2}, {"q": "COMPLETED → RUNNING", "a": 1}], "hints": ["Mỗi quy tắc một chỗ.", "Trạng thái thì transition()."], "why": "Hai lệnh chạy: chỉ mục; chuyển sai: transition(); gửi lại: UNIQUE erp_ref."}, {"kind": "order", "t": "Từ ERP tới chạy", "d": "<p>Sắp xếp.<\/p>", "items": ["Nhận từ ERP: NEW", "Kế hoạch viên phát cho L1: RELEASED", "Xếp seq trong hàng đợi", "Tổ trưởng bắt đầu: RUNNING", "Ghi mã sản phẩm xuống PLC (Bài 81)"], "hints": ["Phát trước khi xếp.", "Bắt tay PLC sau khi bắt đầu."], "why": "NEW → RELEASED → seq → RUNNING → D110."}]);
mesSim(document.getElementById("sim-l78"),Object.assign({id:"l78"},{kind:"db",title:"Hàng đợi và một lệnh chạy mỗi chuyền",sub:"Bảng work_order có chỉ mục duy nhất một phần one_running_per_line ON (line_id) WHERE status = 'RUNNING'.",show:"work_order",
 tables:[{name:"work_order",cols:[{n:"wo_id",ty:"text",pk:1},{n:"product_id",ty:"text"},{n:"line_id",ty:"text"},{n:"status",ty:"text"},{n:"seq",ty:"int"},{n:"due",ty:"timestamptz"}],
   unique:[{cols:["line_id"],where:"status = 'RUNNING'",name:"one_running_per_line"}],
   rows:[{wo_id:"WO-0412",product_id:"SP-07",line_id:"L1",status:"RUNNING",seq:1,due:"2026-11-12 14:00"},{wo_id:"WO-0413",product_id:"SP-08",line_id:"L1",status:"RELEASED",seq:3,due:"2026-11-13 14:00"},
    {wo_id:"WO-0415",product_id:"SP-07",line_id:"L1",status:"RELEASED",seq:2,due:"2026-11-13 22:00"},{wo_id:"WO-0420",product_id:"SP-08",line_id:"L2",status:"RELEASED",seq:1,due:"2026-11-13 14:00"}]}],
 sql:"SELECT wo_id, product_id, qty_hint, due\nFROM work_order\nWHERE line_id = 'L1' AND status = 'RELEASED'\nORDER BY seq, due;",
 samples:[{l:"Chạy WO-0413",sql:"UPDATE work_order SET status = 'RUNNING' WHERE wo_id = 'WO-0413';"},{l:"Đổi lệnh trong giao dịch",sql:"BEGIN;\nUPDATE work_order SET status = 'COMPLETED' WHERE wo_id = 'WO-0412';\nUPDATE work_order SET status = 'RUNNING' WHERE wo_id = 'WO-0415';\nCOMMIT;"},
  {l:"Chạy lệnh chuyền L2",sql:"UPDATE work_order SET status = 'RUNNING' WHERE wo_id = 'WO-0420';"}],
 tasks:[{t:"Truy vấn có sẵn đang lỗi một cột không có. Sửa thành product_id, due và chạy: lệnh nào tiếp theo?",ok:"WO-0415 (seq 2) rồi WO-0413: hai lệnh SP-07 liền nhau, bớt một lần đổi sản phẩm.",check:(s,c)=>c.has("sql",e=>e.ok&&e.rows.length===2&&e.rows[0][0]==="WO-0415")},
  {t:"Thử cho WO-0413 chạy khi WO-0412 đang RUNNING.",ok:"CSDL chặn: không thể biết hộp nào thuộc lệnh nào nếu hai lệnh cùng chạy.",check:(s,c)=>c.has("sql",e=>/one_running_per_line/.test(e.err||""))},
  {t:"Hoàn tất WO-0412 rồi chạy WO-0415 trong cùng giao dịch.",check:s=>s.rows("work_order").some(r=>r.wo_id==="WO-0415"&&r.status==="RUNNING")},
  {t:"Cho WO-0420 chạy trên L2.",ok:"Được: chỉ mục theo line_id, chuyền khác không đụng nhau.",check:s=>s.rows("work_order").some(r=>r.wo_id==="WO-0420"&&r.status==="RUNNING")}]}));

